Bash(curl -s "http://localhost:3000/api/itinerary?city=Seoul&country=South%20Korea&from=Hong%20Kong&startDate=2026-04-01&days=5&prefTime=morning" 2>/dev/null | python3 -c "
import json,sys
d=json.load\(sys.stdin\)
for day in d['itinerary'][:3]:
  print\(f\\"=== Day {day['day']}: {day['theme']} ===\\"\)
  for act in day['activities']:
    if act['category'] in \('food','meal','dining'\):
      print\(f\\"  {act['time']} {act['title']}\\"\)
    elif 'food' in act.get\('title',''\).lower\(\) or 'dinner' in act.get\('title',''\).lower\(\) or 'lunch' in act.get\('title',''\).lower\(\) or 'breakfast' in act.get\('title',''\).lower\(\):
      print\(f\\"  {act['time']} {act['title']}\\"\)
  # show all activities
  for act in day['activities']:
    cat = act.get\('category',''\)
    print\(f\\"  [{cat:10}] {act['time']} {act['title'][:60]}\\"\)
  print\(\)
" 2>/dev/null)

